UPDATE `quest_template` SET `entry`=412, `Method`=2, `ZoneOrSort`=1, `MinLevel`=7, `MaxLevel`=255, `QuestLevel`=10, `Type`=0, `RequiredClasses`=0, `RequiredRaces`=77, `RequiredSkill`=0, `RequiredSkillValue`=0, `RequiredCondition`=0, `RepObjectiveFaction`=0, `RepObjectiveValue`=0, `RequiredMinRepFaction`=0, `RequiredMinRepValue`=0, `RequiredMaxRepFaction`=0, `RequiredMaxRepValue`=0, `SuggestedPlayers`=0, `LimitTime`=0, `QuestFlags`=8, `SpecialFlags`=0, `PrevQuestId`=0, `NextQuestId`=0, `ExclusiveGroup`=0, `BreadcrumbForQuestId`=0, `NextQuestInChain`=0, `SrcItemId`=0, `SrcItemCount`=0, `SrcSpell`=0, `Title`='Operation Recombobulation', `Details`='Upon further analysis of the Gnomeregan situation, it would appear as though we not only failed to eradicate the troggs but we also happened to turn most of the gnomish race into horrific, mindless, evil-doing leper gnomes.$B$BOzzie and I plan to reverse the horrible leper effect with our latest invention: The Recombobulator.  The machine is almost complete but we are in dire need of some Restabilization Cogs and Gyromechanic Gears.  Retrieve some from the leper gnomes out front of Gnomeregan for us.', `Objectives`='Bring Razzle Sprysprocket in Kharanos 8 Restabilization Cogs and 8 Gyromechanic Gears.', `OfferRewardText`='These Gyromechanic Gears and Restabilization Cogs are in perfect accordance with Ozzie\'s schematics for the Recombobulation Device. Once I add some hyrdolubricant to the inner combustion pistons, adjust the crank-o-ratchet and increase of the viscosity of the electrogum gel, the gnomish race will be as good as new.', `RequestItemsText`='The Recombobulator will be up and running as soon as we have sufficient Restabilization Cogs and Gyromechanic Gears.', `EndText`='', `ObjectiveText1`='', `ObjectiveText2`='', `ObjectiveText3`='', `ObjectiveText4`='', `ReqItemId1`=3083, `ReqItemId2`=3084, `ReqItemId3`=0, `ReqItemId4`=0, `ReqItemCount1`=8, `ReqItemCount2`=8, `ReqItemCount3`=0, `ReqItemCount4`=0, `ReqSourceId1`