UPDATE `quest_template` SET `entry`=419, `Method`=2, `ZoneOrSort`=1, `MinLevel`=8, `MaxLevel`=255, `QuestLevel`=10, `Type`=0, `RequiredClasses`=0, `RequiredRaces`=77, `RequiredSkill`=0, `RequiredSkillValue`=0, `RequiredCondition`=0, `RepObjectiveFaction`=0, `RepObjectiveValue`=0, `RequiredMinRepFaction`=0, `RequiredMinRepValue`=0, `RequiredMaxRepFaction`=0, `RequiredMaxRepValue`=0, `SuggestedPlayers`=0, `LimitTime`=0, `QuestFlags`=8, `SpecialFlags`=0, `PrevQuestId`=0, `NextQuestId`=0, `ExclusiveGroup`=0, `BreadcrumbForQuestId`=0, `NextQuestInChain`=417, `SrcItemId`=0, `SrcItemCount`=0, `SrcSpell`=0, `Title`='The Lost Pilot', `Details`='My friend and fellow Siege Engine pilot, Mori Hildelve, is lost in the hills.  We were looking for a rare ore that\'s needed for a high-grade blastpowder, and during our search he drove his engine up a steep hill and busted it!$B$BStill convinced that ore was in these mountains, Hildelve charged me to guard our engines while he continued on foot, searching.$B$BIt\'s been days, and I\'ve heard some beastly growls in the hills at night.  Mori\'s tough as nails, but I\'m worried.$B$BPlease, $N.  Find him.', `Objectives`='Find Pilot Hildelve.', `OfferRewardText`='Here is the corpse of a dwarf -- mauled, frozen, and picked clean by mountain scavengers. Clutched in its hand is a book containing the roughly scribbled notes of Mori Hildelve. And around its frame, still in superior condition, is a Brigadier\'s Vest.$B$BThis grisly scene must have been where the Siege Engine pilot met his end.', `RequestItemsText`=NULL, `EndText`='', `ObjectiveText1`='', `ObjectiveText2`='', `ObjectiveText3`='', `ObjectiveText4`='', `ReqItemId1`=0, `ReqItemId2`=0, `ReqItemId3`=0, `ReqItemId4`=0, `ReqItemCount1`=0, `ReqItemCount2`=0, `ReqItemCount3`=0, `ReqItemCount4`=0, `ReqSourceId1`=0, `ReqSourceId2`=0, `ReqSourceId3`=0, `ReqSourceId4`=0, `ReqSourceCount1`=0, `ReqSourceCount2`=0, `ReqSourceCount3`=0, `ReqSourceCount4`=0, `ReqCreatureOrGOId1`=0, `ReqCreatureOr